// Album recordings live independently of portable tape projects, in local IndexedDB.
export function albumHeader(rate,frames){const b=new Uint8Array(44),v=new DataView(b.buffer);const text=(at,s)=>[...s].forEach((c,i)=>b[at+i]=c.charCodeAt(0));text(0,'RIFF');v.setUint32(4,36+frames*6,true);text(8,'WAVE');text(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,2,true);v.setUint32(24,rate,true);v.setUint32(28,rate*6,true);v.setUint16(32,6,true);v.setUint16(34,24,true);text(36,'data');v.setUint32(40,frames*6,true);return b;}
export function albumPCM(data,frames=data.length/2){const b=new Uint8Array(frames*6);for(let i=0;i<frames*2;i++){const value=Math.round(Math.max(-1,Math.min(1,Number.isFinite(data[i])?data[i]:0))*8388607);b[i*3]=value&255;b[i*3+1]=(value>>8)&255;b[i*3+2]=(value>>16)&255;}return b;}
const req=r=>new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
const done=t=>new Promise((resolve,reject)=>{t.oncomplete=resolve;t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error??Error('Album storage interrupted'));});
export class AlbumStore {
 async open(){if(this.db)return this.db;if(!globalThis.indexedDB)throw Error('Local album storage is unavailable in this browser');const r=indexedDB.open('pxl-tape-albums',1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('takes',{keyPath:'id'});d.createObjectStore('chunks',{keyPath:['take','index']});d.createObjectStore('sides',{keyPath:'side'});};this.db=await req(r);return this.db;}
 async current(side){const d=await this.open(),t=d.transaction(['takes','sides'],'readonly'),s=await req(t.objectStore('sides').get(side));return s?await req(t.objectStore('takes').get(s.take)):null;}
 async begin(side,rate){const d=await this.open(),take={id:crypto.randomUUID(),side,rate,frames:0,chunks:0,complete:false,started:Date.now()},t=d.transaction(['takes','sides'],'readwrite'),sides=t.objectStore('sides'),old=await req(sides.get(side));t.objectStore('takes').put(take);sides.put({side,take:take.id,previous:old?.take??null});await done(t);return take;}
 async append(take,index,data,frames){const d=await this.open(),t=d.transaction(['takes','chunks'],'readwrite');t.objectStore('chunks').put({take:take.id,index,frames,data:data.slice(0,frames*2).buffer});const stored=await req(t.objectStore('takes').get(take.id));stored.frames+=frames;stored.chunks++;t.objectStore('takes').put(stored);await done(t);take.frames=stored.frames;take.chunks=stored.chunks;}
 async finish(take,error=null){const d=await this.open(),t=d.transaction('takes','readwrite'),stored=await req(t.objectStore('takes').get(take.id));stored.complete=true;stored.error=error;t.objectStore('takes').put(stored);await done(t);return stored;}
 async previous(side){const d=await this.open(),t=d.transaction('sides','readwrite'),s=t.objectStore('sides'),old=await req(s.get(side));if(!old?.previous)return false;s.put({side,take:old.previous,previous:old.take});await done(t);return true;}
 async wav(side){const take=await this.current(side);if(!take?.frames)throw Error('Record this side first');const parts=[albumHeader(take.rate,take.frames)],d=await this.open();for(let index=0;index<take.chunks;index++){const t=d.transaction('chunks','readonly'),chunk=await req(t.objectStore('chunks').get([take.id,index]));if(!chunk)throw Error('Album chunk missing; current tape is preserved');parts.push(albumPCM(new Float32Array(chunk.data),chunk.frames));}return {blob:new Blob(parts,{type:'audio/wav'}),take};}
}
export class AlbumController {
 constructor({enable,request,send,rate,notice,download,change}){Object.assign(this,{enable,request,send,rate,notice,download,change});this.store=new AlbumStore();this.active=null;this.pending=Promise.resolve();this.received=0;this.count=0;this.recording=false;this.waiters=[];this.sides={A:null,B:null};}
 async refresh(){for(const side of ['A','B'])this.sides[side]=await this.store.current(side);this.change();}
 async start(side){if(this.starting||this.active||this.stopping)return;this.starting=true;this.change();try{await this.enable();this.active=await this.store.begin(side,this.rate());this.received=0;this.count=0;this.index=0;this.error=null;this.pending=Promise.resolve();const take=this.active;await this.request('album-start');if(this.active!==take||this.stopping)return;this.recording=true;this.notice(`Album ${side} recording the live master. Tape and patch changes are captured.`);}catch(error){this.send({type:'album-stop'});const take=this.active;this.active=null;this.recording=false;if(take)await this.store.finish(take,error.message).catch(()=>{});await this.refresh().catch(()=>{});throw error;}finally{this.starting=false;this.change();}}
 receive(m){if(!this.active){this.send({type:'album-recycle',data:m.data},[m.data]);return;}const take=this.active,index=this.index++;this.received+=m.n;this.pending=this.pending.then(async()=>{if(!this.error)await this.store.append(take,index,new Float32Array(m.data),m.n);}).catch(error=>{this.error=error.message||'Album storage is full';this.notice('Album stopped: local storage could not keep up. The stored prefix is preserved.');if(!this.stopping)this.stop();}).finally(()=>{this.send({type:'album-recycle',data:m.data},[m.data]);for(const wake of this.waiters.splice(0))wake();});}
 status(s){this.count=s.frames;if(this.recording&&!s.recording&&!this.stopping)this.stop();this.change();}
 async stop(){if(this.stopping)return this.stopping;if(!this.active)return;this.recording=false;this.change();this.stopping=(async()=>{const take=this.active;let meta;try{meta=await this.request('album-stop');}catch(error){this.send({type:'album-stop'});this.error=error.message;meta={frames:this.received,overflow:false};}const deadline=Date.now()+10000;while(this.received<meta.frames&&Date.now()<deadline)await new Promise(resolve=>{const timer=setTimeout(resolve,50);this.waiters.push(()=>{clearTimeout(timer);resolve();});});await this.pending;if(this.received<meta.frames)this.error='Album delivery interrupted';if(meta.overflow)this.error='Storage could not keep up';try{await this.store.finish(take,this.error);}catch(error){this.error=error.message;}this.active=null;this.recording=false;this.notice(this.error?'Album stopped. Stored prefix kept; export the side to recover it.':'Album take saved locally. Export WAV for a portable copy.');await this.refresh();})().finally(()=>{this.stopping=null;this.change();});return this.stopping;}
 async export(side,listen=false){if(this.active)await this.stop();const {blob}=await this.store.wav(side);if(listen){this.download(blob,`PXL-Album-${side}.wav`,'audio/wav');}else this.download(blob,`PXL-Album-${side}.wav`,'audio/wav');this.notice(`Album ${side} exported as stereo24-bit WAV.`);}
}
